1	/**
2	 * Bulk-import the real Modrinth catalogue into `GameMod` — the "genuine
3	 * scale" pass NxLabs never had. Separate from `scripts/verify-gamemods.ts`,
4	 * which stays the per-mod re-verification/freshness-check tool for rows that
5	 * already exist (this script creates/updates rows in the first place; run
6	 * verify-gamemods.ts afterward on a schedule to keep them fresh and to
7	 * backfill fileBytes/impact/dependencyCount, which this script deliberately
8	 * does not touch — see "WHAT THIS DOES NOT FETCH" below).
9	 *
10	 * WHY THIS EXISTS. As of 2026-09-19 NxLabs has 119 real (of 124 seeded)
11	 * hand-picked mod rows across 5 families. Modrinth alone publishes ~158k real
12	 * projects. This script queries Modrinth's actual public search API, filters
13	 * to content that is genuinely installable on a DEDICATED SERVER (Nxeon's
14	 * product), and upserts real rows — every field traces to a live API
15	 * response, nothing here is fabricated.
16	 *
17	 * SOURCE: Modrinth REST API v2, https://docs.modrinth.com/api/ — a fully
18	 * public, documented, third-party-integration-friendly API (the same one
19	 * `scripts/verify-gamemods.ts` already calls; this script reuses its request
20	 * pattern: identifying User-Agent, optional API key header, real 429/5xx
21	 * backoff, no attempt to mirror/rehost files — only metadata + hotlinked CDN
22	 * images, files are fetched by the worker at install time, same as today).
23	 *
24	 * PROJECT TYPES COVERED: mod, plugin, resourcepack, shader, datapack,
25	 * modpack. Deliberately EXCLUDED: `minecraft_java_server` (Modrinth's own
26	 * dedicated server-jar listing product — not installable "content" the way
27	 * the six above are).
28	 *
29	 * SERVER-RELEVANCE FILTER: Modrinth's `environment` facet says whether a
30	 * project runs client, server, or both. We only import environments that are
31	 * meaningfully server-side: server_only, dedicated_server_only,
32	 * server_only_client_optional, client_and_server, client_or_server,
33	 * client_or_server_prefers_both. We exclude client_only / singleplayer_only
34	 * on purpose — Nxeon hosts dedicated servers, not client mods.
35	 *   ONE DELIBERATE EXCEPTION: for project_type "plugin" we ALSO accept
36	 *   environment "unknown". Reason (checked live against the real API, not
37	 *   guessed): "plugin" on Modrinth structurally means Bukkit/Spigot/
38	 *   Paper/Sponge/Velocity server software — there is no such thing as a
39	 *   client-only plugin — but a large fraction of real, popular, genuinely
40	 *   server-only plugins simply never got the environment field filled in by
41	 *   their author (verified live: project_type:plugin + our environment list
42	 *   + downloads>1000 = 141 hits; the SAME query without the environment
43	 *   filter = 3340 hits, and manually sampling the gap showed real, popular,
44	 *   unambiguously server-side plugins like Chunky and Simple Voice Chat
45	 *   tagged "unknown"/"client_or_server_prefers_both"). Excluding "unknown"
46	 *   for plugins specifically would throw away real, relevant, high-quality
47	 *   catalogue content over a data-entry gap, not a real client/server
48	 *   distinction. Every other project type keeps the strict list, because for
49	 *   mods/resourcepacks/shaders/modpacks "unknown" genuinely can mean
50	 *   client-only.
51	 *
52	 * QUALITY THRESHOLD (script constants below, override with --min-downloads /
53	 * --min-follows): downloads > 1000 OR follows > 50. Implemented as two
54	 * disjoint search passes (Modrinth facets AND within a query; there is no
55	 * single-query OR across two different numeric fields) — pass 1 sorts by
56	 * downloads and takes everything over the download floor, pass 2 sorts by
57	 * follows and takes everything over the follow floor that pass 1 didn't
58	 * already take (`downloads<=floor`), so nothing is double-counted across
59	 * passes (cross-project-type duplicates from Modrinth's own
60	 * `all_project_types` overlap are still possible and handled by the
61	 * `seenProjectIds` set + the `@@unique([gameFamily, slug])` upsert either
62	 * way).
63	 *
64	 * WHAT THIS DOES NOT FETCH (by design, to keep this a fast, few-thousand-
65	 * request bulk pass rather than a many-hour one): fileBytes,
66	 * dependencyCount, impact/impactNote. Those need a per-project `/version`
67	 * call each and are exactly what `verify-gamemods.ts` already does well —
68	 * re-run it with `--source=modrinth` after this script to backfill them, at
69	 * whatever pace is comfortable, on however many thousand rows this leaves it.
70	 *
71	 * EFFICIENCY: uses Modrinth's *bulk* endpoints so a page of 100 search hits
72	 * costs 3 requests total, not ~300: one `/v2/search` call, one
73	 * `/v2/projects?ids=[...]` call for the full record (clean `loaders` array
74	 * separate from tags, real `license` object, full `gallery` with
75	 * featured/ordering metadata, `server_side`), and one `/v2/users?ids=[...]`
76	 * call for real author avatars (search hits already carry `author`/
77	 * `author_id` directly — no team-lookup round trip needed the way a
78	 * single-project verify does).
79	 *
80	 * RATE LIMIT: 300 req/min per Modrinth, same with or without the API key (the
81	 * key just avoids being rejected as an unidentified client — real
82	 * contact-bearing User-Agent sent regardless). This script paces itself under
83	 * that (see RATE_LIMIT_PER_MIN) and retries 429s honoring `Retry-After`.
84	 *
85	 * IDEMPOTENT: every write is `db.gameMod.upsert` on the real
86	 * `@@unique([gameFamily, slug])` constraint — re-running updates the same
87	 * rows, never duplicates.
88	 *
89	 * SAFETY: this is a bulk-WRITE script against a real database, so it goes
90	 * through the same NXEON_DB_TARGET confirmation every other writing script in
91	 * this repo uses (scripts/db-target-guard.ts) and defaults to a dry run.
92	 *
93	 *   Dry run (no writes), one type, tiny slice — the sane way to first try this:
94	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modrinth-catalog.ts \
95	 *       --project-types=mod --max-pages=1
96	 *
97	 *   Real write, one type, tiny slice:
98	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modrinth-catalog.ts \
99	 *       --project-types=mod --max-pages=1 --apply
100	 *
101	 *   Full real run (all 6 types, default thresholds):
102	 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-modrinth-catalog.ts --apply
103	 */
104	
105	import { assertDbTarget } from "./db-target-guard";
106	assertDbTarget("import-modrinth-catalog.ts");
107	
108	import { db } from "../lib/db";
109	
110	const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
111	const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
112	const API = "https://api.modrinth.com/v2";
113	
114	// ── Tunable script constants (all overridable via CLI flags, see parseArgs) ──
115	const DEFAULT_MIN_DOWNLOADS = 1000;
116	const DEFAULT_MIN_FOLLOWS = 50;
117	const DEFAULT_RATE_LIMIT_PER_MIN = 280; // stay under Modrinth's real 300/min
118	const PAGE_SIZE = 100; // Modrinth's real server-side cap on `limit`
119	const GALLERY_CAP = 8; // matches verify-gamemods.ts's convention
120	
121	const ALL_PROJECT_TYPES = ["mod", "plugin", "resourcepack", "shader", "datapack", "modpack"] as const;
122	type ProjectType = (typeof ALL_PROJECT_TYPES)[number];
123	
124	const CATEGORY_LABEL: Record<ProjectType, string> = {
125	  mod: "Mods",
126	  plugin: "Plugins",
127	  resourcepack: "Resource Packs",
128	  shader: "Shaders",
129	  datapack: "Datapacks",
130	  modpack: "Modpacks",
131	};
132	
133	/** Real, server-relevant Modrinth `environment` values (see file header). */
134	const SERVER_ENVIRONMENTS = [
135	  "server_only",
136	  "dedicated_server_only",
137	  "server_only_client_optional",
138	  "client_and_server",
139	  "client_or_server",
140	  "client_or_server_prefers_both",
141	];
142	
143	function environmentsFor(pt: ProjectType): string[] {
144	  // See file header: plugins are structurally server-only software even when
145	  // the author never filled in the environment field.
146	  return pt === "plugin" ? [...SERVER_ENVIRONMENTS, "unknown"] : SERVER_ENVIRONMENTS;
147	}
148	
149	// ── CLI args ──────────────────────────────────────────────────────────────
150	function parseArgs(argv: string[]) {
151	  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
152	  const projectTypesArg = get("project-types");
153	  const projectTypes = (projectTypesArg ? projectTypesArg.split(",") : [...ALL_PROJECT_TYPES]).filter(
154	    (t): t is ProjectType => (ALL_PROJECT_TYPES as readonly string[]).includes(t)
155	  );
156	  return {
157	    apply: argv.includes("--apply"),
158	    minDownloads: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS),
159	    minFollows: Number(get("min-follows") ?? DEFAULT_MIN_FOLLOWS),
160	    ratePerMin: Number(get("rate-per-min") ?? DEFAULT_RATE_LIMIT_PER_MIN),
161	    // Cap pages PER (project type × pass) — for smoke-testing a slice, not a real-run knob.
162	    maxPages: get("max-pages") ? Number(get("max-pages")) : undefined,
163	    projectTypes: projectTypes.length ? projectTypes : [...ALL_PROJECT_TYPES],
164	  };
165	}
166	
167	// ── Rate-limited, retrying fetch ─────────────────────────────────────────
168	class RateLimiter {
169	  private minIntervalMs: number;
170	  private last = 0;
171	  constructor(perMin: number) {
172	    this.minIntervalMs = 60_000 / perMin;
173	  }
174	  async wait() {
175	    const now = Date.now();
176	    const elapsed = now - this.last;
177	    if (elapsed < this.minIntervalMs) {
178	      await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
179	    }
180	    this.last = Date.now();
181	  }
182	}
183	
184	async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
185	  await limiter.wait();
186	  const headers: Record<string, string> = { "User-Agent": UA };
187	  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
188	  const res = await fetch(url, { headers });
189	  if (res.status === 429 && attempt <= 6) {
190	    const retryAfterHeader = res.headers.get("retry-after");
191	    const retryAfterMs = retryAfterHeader ? Number(retryAfterHeader) * 1000 : 0;
192	    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
193	    console.warn(`  [rate-limit] 429 on ${url} — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
194	    await new Promise((r) => setTimeout(r, backoffMs));
195	    return apiFetch(limiter, url, attempt + 1);
196	  }
197	  if (res.status >= 500 && attempt <= 4) {
198	    const backoffMs = 1000 * 2 ** attempt;
199	    console.warn(`  [server-error] ${res.status} on ${url} — retrying in ${Math.round(backoffMs / 1000)}s`);
200	    await new Promise((r) => setTimeout(r, backoffMs));
201	    return apiFetch(limiter, url, attempt + 1);
202	  }
203	  return res;
204	}
205	
206	// ── Modrinth types (only the fields we read) ─────────────────────────────
207	type SearchHit = {
208	  project_id: string;
209	  project_type: string;
210	  slug: string;
211	  author: string | null;
212	  author_id: string | null;
213	  title: string;
214	  description: string;
215	  downloads: number;
216	  follows: number;
217	  icon_url: string | null;
218	};
219	type SearchResponse = { hits: SearchHit[]; total_hits: number };
220	
221	type FullProject = {
222	  id: string;
223	  slug: string;
224	  license?: { id?: string | null; name?: string | null } | null;
225	  game_versions?: string[];
226	  loaders?: string[];
227	  server_side?: string;
228	  downloads?: number;
229	  followers?: number;
230	  icon_url?: string | null;
231	  gallery?: Array<{ url: string; featured?: boolean; ordering?: number }>;
232	};
233	
234	type UserRecord = { id: string; username: string; avatar_url?: string | null };
235	
236	function facetQuery(pt: ProjectType, envs: string[], extra: string[], limit: number, offset: number, sortIndex: string): string {
237	  const facets = [[`project_type:${pt}`], envs.map((e) => `environment:${e}`), ...extra.map((e) => [e])];
238	  const encoded = encodeURIComponent(JSON.stringify(facets));
239	  return `${API}/search?facets=${encoded}&limit=${limit}&offset=${offset}&index=${sortIndex}`;
240	}
241	
242	/** Real gallery URLs, featured-first then by real `ordering`, capped — matches verify-gamemods.ts. */
243	function galleryUrlsFrom(gallery: FullProject["gallery"]): string[] {
244	  return (gallery ?? [])
245	    .slice()
246	    .sort((a, b) => Number(b.featured) - Number(a.featured) || (a.ordering ?? 0) - (b.ordering ?? 0))
247	    .slice(0, GALLERY_CAP)
248	    .map((g) => g.url);
249	}
250	
251	type Counters = { searched: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
252	function emptyCounters(): Counters {
253	  return { searched: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
254	}
255	
256	async function importPass(opts: {
257	  pt: ProjectType;
258	  facetsExtra: string[];
259	  sortIndex: string;
260	  limiter: RateLimiter;
261	  apply: boolean;
262	  maxPages?: number;
263	  seenProjectIds: Set<string>;
264	  counters: Counters;
265	}) {
266	  const { pt, facetsExtra, sortIndex, limiter, apply, maxPages, seenProjectIds, counters } = opts;
267	  const envs = environmentsFor(pt);
268	  let offset = 0;
269	  let page = 0;
270	  // First call establishes total_hits; loop until we've paged through it (or hit --max-pages).
271	  for (;;) {
272	    if (maxPages !== undefined && page >= maxPages) break;
273	    const url = facetQuery(pt, envs, facetsExtra, PAGE_SIZE, offset, sortIndex);
274	    const res = await apiFetch(limiter, url);
275	    if (!res.ok) {
276	      console.error(`  [search] ${pt} offset=${offset} → HTTP ${res.status}, stopping this pass early`);
277	      break;
278	    }
279	    const body = (await res.json()) as SearchResponse;
280	    page++;
281	    counters.searched += body.hits.length;
282	    if (body.hits.length === 0) break;
283	
284	    const fresh = body.hits.filter((h) => !seenProjectIds.has(h.project_id));
285	    for (const h of fresh) seenProjectIds.add(h.project_id);
286	
287	    if (fresh.length > 0) {
288	      // Bulk-fetch full project records (loaders/license/gallery/server_side) —
289	      // one request for up to 100 mods, per the file header's efficiency note.
290	      const idsParam = encodeURIComponent(JSON.stringify(fresh.map((h) => h.project_id)));
291	      const projRes = await apiFetch(limiter, `${API}/projects?ids=${idsParam}`);
292	      const fullProjects: FullProject[] = projRes.ok ? await projRes.json() : [];
293	      const fullById = new Map(fullProjects.map((p) => [p.id, p]));
294	
295	      // Bulk-fetch real author avatars for every unique author_id on this page.
296	      const authorIds = [...new Set(fresh.map((h) => h.author_id).filter((x): x is string => !!x))];
297	      let userById = new Map<string, UserRecord>();
298	      if (authorIds.length > 0) {
299	        const uidsParam = encodeURIComponent(JSON.stringify(authorIds));
300	        const usersRes = await apiFetch(limiter, `${API}/users?ids=${uidsParam}`);
301	        if (usersRes.ok) {
302	          const users: UserRecord[] = await usersRes.json();
303	          userById = new Map(users.map((u) => [u.id, u]));
304	        }
305	      }
306	
307	      // DB writes are local Postgres — safe to run a small batch concurrently
308	      // (the API calls above stay strictly sequential/rate-limited; this isn't).
309	      const CONCURRENCY = 8;
310	      for (let i = 0; i < fresh.length; i += CONCURRENCY) {
311	        const slice = fresh.slice(i, i + CONCURRENCY);
312	        await Promise.all(
313	          slice.map(async (hit) => {
314	            if (!hit.slug) {
315	              counters.skipped++;
316	              return;
317	            }
318	            const full = fullById.get(hit.project_id);
319	            const author = hit.author_id ? userById.get(hit.author_id) : undefined;
320	            const data = {
321	              name: hit.title,
322	              category: CATEGORY_LABEL[pt],
323	              description: hit.description || null,
324	              iconUrl: full?.icon_url ?? hit.icon_url ?? null,
325	              url: `https://modrinth.com/${pt}/${hit.slug}`,
326	              downloads: full?.downloads ?? hit.downloads ?? null,
327	              license: full?.license?.id || full?.license?.name || null,
328	              gameVersions: full?.game_versions ?? [],
329	              loaders: full?.loaders ?? [],
330	              serverSide: full?.server_side ?? null,
331	              galleryUrls: galleryUrlsFrom(full?.gallery),
332	              authorName: hit.author ?? null,
333	              authorAvatarUrl: author?.avatar_url ?? null,
334	              source: "modrinth",
335	              sourceId: hit.slug,
336	              active: true,
337	              verifiedAt: new Date(),
338	              upstreamOk: true,
339	              upstreamNote: null,
340	            };
341	            if (!apply) {
342	              counters.upserted++;
343	              return;
344	            }
345	            try {
346	              const existing = await db.gameMod.findUnique({
347	                where: { gameFamily_slug: { gameFamily: "minecraft", slug: hit.slug } },
348	                select: { id: true },
349	              });
350	              await db.gameMod.upsert({
351	                where: { gameFamily_slug: { gameFamily: "minecraft", slug: hit.slug } },
352	                update: data,
353	                create: { gameFamily: "minecraft", slug: hit.slug, ...data },
354	              });
355	              counters.upserted++;
356	              if (existing) counters.updated++;
357	              else counters.created++;
358	            } catch (e) {
359	              counters.failed++;
360	              const msg = e instanceof Error ? e.message : String(e);
361	              console.error(`  [db] failed to upsert ${pt}/${hit.slug}: ${msg}`);
362	            }
363	          })
364	        );
365	      }
366	    }
367	
368	    console.log(
369	      `  [${pt}/${sortIndex}] page=${page} offset=${offset} hits=${body.hits.length} fresh=${fresh.length} total_hits=${body.total_hits} ` +
370	        `(running: searched=${counters.searched} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed})`
371	    );
372	
373	    offset += PAGE_SIZE;
374	    if (offset >= body.total_hits) break;
375	  }
376	}
377	
378	async function main() {
379	  const args = parseArgs(process.argv.slice(2));
380	  console.log(
381	    `[import-modrinth-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
382	      `project types: ${args.projectTypes.join(", ")}; threshold: downloads>${args.minDownloads} OR follows>${args.minFollows}; ` +
383	      `rate: ${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
384	  );
385	
386	  const limiter = new RateLimiter(args.ratePerMin);
387	  const seenProjectIds = new Set<string>();
388	  const totals = emptyCounters();
389	  const perType: Record<string, Counters> = {};
390	
391	  for (const pt of args.projectTypes) {
392	    const counters = emptyCounters();
393	    perType[pt] = counters;
394	    console.log(`\n=== ${pt} ===`);
395	
396	    // Pass 1: downloads > floor, sorted by downloads (highest quality first).
397	    await importPass({
398	      pt,
399	      facetsExtra: [`downloads>${args.minDownloads}`],
400	      sortIndex: "downloads",
401	      limiter,
402	      apply: args.apply,
403	      maxPages: args.maxPages,
404	      seenProjectIds,
405	      counters,
406	    });
407	
408	    // Pass 2: follows > floor AND downloads <= floor (disjoint from pass 1),
409	    // sorted by follows — catches real, followed-but-newer projects pass 1 missed.
410	    await importPass({
411	      pt,
412	      facetsExtra: [`follows>${args.minFollows}`, `downloads<=${args.minDownloads}`],
413	      sortIndex: "follows",
414	      limiter,
415	      apply: args.apply,
416	      maxPages: args.maxPages,
417	      seenProjectIds,
418	      counters,
419	    });
420	
421	    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
422	    console.log(
423	      `--- ${pt} done: searched=${counters.searched} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed} ---`
424	    );
425	  }
426	
427	  console.log(`\n============================================================`);
428	  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
429	  for (const pt of args.projectTypes) {
430	    const c = perType[pt]!;
431	    console.log(
432	      `  ${pt.padEnd(13)} searched=${c.searched.toString().padStart(6)} upserted=${c.upserted.toString().padStart(6)} created=${c.created.toString().padStart(6)} updated=${c.updated.toString().padStart(6)} skipped=${c.skipped} failed=${c.failed}`
433	    );
434	  }
435	  console.log(`  ${"TOTAL".padEnd(13)} searched=${totals.searched.toString().padStart(6)} upserted=${totals.upserted.toString().padStart(6)} created=${totals.created.toString().padStart(6)} updated=${totals.updated.toString().padStart(6)} skipped=${totals.skipped} failed=${totals.failed}`);
436	  console.log(`  unique projects seen across all passes: ${seenProjectIds.size}`);
437	}
438	
439	main()
440	  .then(() => process.exit(0))
441	  .catch((e) => {
442	    console.error(e);
443	    process.exit(1);
444	  });
445

1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
5	import { Client, type ClientChannel } from "ssh2";
6	import type { Job } from "@prisma/client";
7	
8	/**
9	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
10	 * state recorded in `ServerMod` rows:
11	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
12	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
13	 *
14	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
15	 *
16	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
17	 * mod is installed when nothing was written to their server:
18	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
19	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
20	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
21	 *    FAILED with a clear reason — never silently "INSTALLED".
22	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
23	 *    message. A change we did NOT apply is a failure and must say so.
24	 */
25	
26	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
27	
28	async function notify(userId: string, title: string, body?: string, href?: string) {
29	  try {
30	    await db.notification.create({ data: { userId, title, body, href } });
31	  } catch (e) {
32	    console.error("[game-mods] notify failed", e);
33	  }
34	}
35	
36	export async function gameModSync(job: Job): Promise<void> {
37	  const serverId = job.serverId;
38	  if (!serverId) throw new Error("game mod sync: job has no serverId");
39	
40	  const server = await db.server.findUnique({
41	    where: { id: serverId },
42	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
43	  });
44	  if (!server) throw new Error(`Server ${serverId} not found`);
45	
46	  const pending = await db.serverMod.findMany({
47	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
48	    include: { mod: true },
49	  });
50	  if (pending.length === 0) return;
51	
52	  const installedNames: string[] = [];
53	  const removedNames: string[] = [];
54	  const failedNames: string[] = [];
55	
56	  for (const sm of pending) {
57	    const removing = sm.status === "REMOVING";
58	    try {
59	      if (SANDBOX) {
60	        // Dev simulation — no VM mutation.
61	        if (removing) {
62	          await db.serverMod.delete({ where: { id: sm.id } });
63	          removedNames.push(sm.mod.name);
64	        } else {
65	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
66	          installedNames.push(sm.mod.name);
67	        }
68	        continue;
69	      }
70	
71	      if (!REAL_ENABLED) {
72	        // Honest failure: nothing was applied. Do NOT report success.
73	        await db.serverMod.update({
74	          where: { id: sm.id },
75	          data: {
76	            status: "FAILED",
77	            error:
78	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
79	          },
80	        });
81	        failedNames.push(sm.mod.name);
82	        continue;
83	      }
84	
85	      // REAL path — install/remove over SSH via the per-source adapter.
86	      const modRow: ModRowFull = {
87	        gameFamily: sm.mod.gameFamily,
88	        source: sm.mod.source,
89	        sourceId: sm.mod.sourceId,
90	        slug: sm.mod.slug,
91	        name: sm.mod.name,
92	        url: sm.mod.url,
93	        variant: server.gameVariant ?? null,
94	        appliesTo: sm.mod.appliesToVariant ?? null,
95	      };
96	      const result = removing ? await removeModReal(server, modRow) : await installModReal(server, modRow);
97	
98	      if (result.ok) {
99	        if (removing) {
100	          await db.serverMod.delete({ where: { id: sm.id } });
101	          removedNames.push(sm.mod.name);
102	        } else {
103	          await db.serverMod.update({
104	            where: { id: sm.id },
105	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
106	          });
107	          installedNames.push(sm.mod.name);
108	        }
109	      } else {
110	        await db.serverMod.update({
111	          where: { id: sm.id },
112	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
113	        });
114	        failedNames.push(sm.mod.name);
115	      }
116	    } catch (e) {
117	      const msg = e instanceof Error ? e.message : String(e);
118	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
119	      await db.serverMod.update({
120	        where: { id: sm.id },
121	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
122	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
123	      });
124	      failedNames.push(sm.mod.name);
125	    }
126	  }
127	
128	  // One summary notification for the batch.
129	  const parts: string[] = [];
130	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
131	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
132	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
133	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
134	  const allFailed = !anyOk && failedNames.length > 0;
135	
136	  await notify(
137	    server.userId,
138	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
139	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
140	    `/dashboard/servers/${server.id}?tab=mods`
141	  );
142	}
