/**
 * Verify every seeded GameMod row against its real upstream source and write
 * back the facts the catalogue/install UI needs: iconUrl, downloads, license,
 * gameVersions, loaders, fileBytes, dependencyCount, serverSide, impact,
 * impactNote, verifiedAt, upstreamOk (+ upstreamNote).
 *
 * WHY THIS EXISTS. Every one of those fields has sat null/zero/true (the
 * default) on all 124 seeded rows since the catalogue was seeded — nothing in
 * this repo ever populated them. `lib/actions-mods.ts` and
 * `components/customer/gamepanel/v2/ModsPanel.tsx` both already read them and
 * both already say, in their own comments, that this script is what fills
 * them in. It also doubles as the "mark as no longer supported" mechanism the
 * owner asked for: re-running this periodically flips `upstreamOk` to false
 * (with a human-readable `upstreamNote`) the moment a project disappears
 * upstream, and the catalogue (getServerMods, and the public NxLabs pages)
 * already filter on `upstreamOk`.
 *
 * SOURCES COVERED THIS PASS: modrinth, spigotmc (via the public Spiget API),
 * thunderstore — the same three `worker/game-mods.ts` already knows how to
 * install from (RESOLVABLE_SOURCES in lib/mod-install-support.ts), so "we can
 * verify it" and "we can install it" track the same source list on purpose.
 * umod / github / nexus / codefling are deliberately left alone here — none of
 * them has a lightweight, well-documented "give me this exact project's
 * metadata by id" endpoint the way the three above do (umod.org has no public
 * read API at all; GitHub/Nexus would need per-repo/per-file heuristics with
 * real risk of wrong data). Their rows simply keep verifiedAt: null, which the
 * UI already renders as "unverified" rather than a fabricated tick — see
 * ModsPanel.tsx's comment on exactly this. Wiring those up is real, separate
 * follow-up work, not a blocker for shipping the majority (58 of 124 rows).
 *
 * IDEMPOTENT + RE-RUNNABLE: safe to run on a cron. Every write is a fresh
 * fetch-and-overwrite of the verified fields for that one row; nothing here
 * depends on the previous state except to compare for the summary counts.
 *
 * Run:  cd /opt/nxeon && npx tsx scripts/verify-gamemods.ts [--source=modrinth] [--limit=20]
 */
import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mod-verify; +https://nxeon.cloud)";
const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";

type VerifyResult =
  | {
      ok: true;
      iconUrl: string | null;
      downloads: number | null;
      license: string | null;
      gameVersions: string[];
      loaders: string[];
      fileBytes: number | null;
      dependencyCount: number;
      serverSide: string | null;
      /** Real gallery/screenshot URLs from the source. Empty when it has none. */
      galleryUrls: string[];
      /** Real creator/team name + avatar, when the source resolves one. */
      authorName: string | null;
      authorAvatarUrl: string | null;
    }
  | { ok: false; note: string };

/** light | moderate | heavy from real file size, plus a customer-facing note for the heavier tiers. */
function impactFromBytes(bytes: number | null): { impact: string; impactNote: string | null } {
  if (!bytes || bytes <= 0) return { impact: "light", impactNote: null };
  const mb = bytes / (1024 * 1024);
  if (mb >= 60) {
    return { impact: "heavy", impactNote: `Large download (~${Math.round(mb)} MB) — expect a slower install and a heavier footprint on your plan.` };
  }
  if (mb >= 12) {
    return { impact: "moderate", impactNote: `Medium-sized download (~${Math.round(mb)} MB).` };
  }
  return { impact: "light", impactNote: null };
}

