async function main() {
  const args = process.argv.slice(2);
  const sourceArg = args.find((a) => a.startsWith("--source="))?.split("=")[1];
  const limitArg = args.find((a) => a.startsWith("--limit="))?.split("=")[1];
  const limit = limitArg ? Number(limitArg) : undefined;

  const sources = sourceArg ? [sourceArg] : Object.keys(VERIFIERS);
  const unsupported = sourceArg && !VERIFIERS[sourceArg];
  if (unsupported) {
    console.error(`No verifier for source "${sourceArg}". Supported: ${Object.keys(VERIFIERS).join(", ")}`);
    process.exit(1);
  }

  const mods = await db.gameMod.findMany({
    where: { source: { in: sources }, sourceId: { not: null } },
    orderBy: [{ gameFamily: "asc" }, { name: "asc" }],
    ...(limit ? { take: limit } : {}),
  });

  console.log(`Verifying ${mods.length} mod(s) across source(s): ${sources.join(", ")}`);

  let verified = 0;
  let failed = 0;
  let skipped = 0;

  for (const mod of mods) {
    const verifier = VERIFIERS[mod.source];
    if (!verifier || !mod.sourceId) {
      skipped++;
      continue;
    }
    try {
      const result = await verifier(mod.sourceId);
      if (result.ok) {
        const { impact, impactNote } = impactFromBytes(result.fileBytes);
        await db.gameMod.update({
          where: { id: mod.id },
          data: {
            iconUrl: result.iconUrl,
            downloads: result.downloads,
            license: result.license,
            gameVersions: result.gameVersions,
            loaders: result.loaders,
            fileBytes: result.fileBytes,
            dependencyCount: result.dependencyCount,
            serverSide: result.serverSide,
            galleryUrls: result.galleryUrls,
            authorName: result.authorName,
            authorAvatarUrl: result.authorAvatarUrl,
            impact,
            impactNote,
            verifiedAt: new Date(),
            upstreamOk: true,
            upstreamNote: null,
          },
        });
        verified++;
        console.log(
          `  OK    ${mod.gameFamily}/${mod.slug} (${mod.source}) — downloads=${result.downloads ?? "?"} icon=${result.iconUrl ? "yes" : "no"} gallery=${result.galleryUrls.length} author=${result.authorName ?? "?"}`
        );
      } else {
        await db.gameMod.update({
          where: { id: mod.id },
          data: { upstreamOk: false, upstreamNote: result.note, verifiedAt: new Date() },
        });
        failed++;
        console.log(`  DEAD  ${mod.gameFamily}/${mod.slug} (${mod.source}) — ${result.note}`);
      }
    } catch (e) {
      failed++;
      const msg = e instanceof Error ? e.message : String(e);
      console.error(`  ERROR ${mod.gameFamily}/${mod.slug} (${mod.source}): ${msg}`);
    }
    // Be a polite API citizen — small delay between calls, no need to hammer
    // free public endpoints for a 124-row catalogue.
    await new Promise((r) => setTimeout(r, 150));
  }

  const totalCatalog = await db.gameMod.count();
  const stillUnverified = await db.gameMod.count({ where: { verifiedAt: null } });
  console.log(
    `\nDone. verified=${verified} dead=${failed} skipped(no-verifier-or-id)=${skipped}. ` +
      `Catalog total=${totalCatalog}, still unverified (other sources)=${stillUnverified}.`
  );
}

