 *
 * SOURCE: Thunderstore's public v1 catalogue API,
 * `https://thunderstore.io/c/{community}/api/v1/package/` — fully open, no
 * auth, no documented rate limit. Unlike Modrinth this is NOT a paged search
 * endpoint: one GET returns the community's ENTIRE package list as a single
 * JSON array (confirmed live 2026-09-20: valheim alone is ~11.5k packages /
 * ~168MB of JSON, because every package embeds its full version history).
 * So this script makes exactly one HTTP request per community — no rate
 * limiter, no pagination loop, no offset bookkeeping needed at all.
 *
 * ---------------------------------------------------------------------------
 * LEGAL / FETCH-AT-INSTALL-ONLY (do not deviate — established this session)
 * ---------------------------------------------------------------------------
 * Thunderstore publishes NO license field anywhere in the API or manifest
 * spec, and has NO published Terms of Service at all (verified 5 independent
 * ways earlier this session). Default copyright applies to every package.
 * Consequences, both already true of the existing 21 Phase-1 rows and kept
 * true here:
 *   - `license` is always written as `null`. Never fabricate one.
 *   - This script NEVER downloads/mirrors/rehosts an actual mod .zip. It
 *     stores metadata + the hotlinked Thunderstore CDN icon URL only. The
 *     real file is fetched at INSTALL TIME, by the worker
 *     (worker/game-mods.ts's `resolveUrl()` → the experimental per-package
 *     endpoint → a direct curl on the customer's own VM), exactly like today.
 *     This script performs zero downloads of mod content, only the catalogue
 *     JSON itself.
 *
 * ---------------------------------------------------------------------------
 * FIELD SEMANTICS MUST MATCH `scripts/verify-gamemods.ts`'s `verifyThunderstore()`
 * ---------------------------------------------------------------------------
 * That function is the periodic freshness pass for every thunderstore row
 * (this repo's real, already-shipped precedent for what "the truth" looks
 * like for this source) and it unconditionally OVERWRITES license,
 * gameVersions, loaders, fileBytes, serverSide, and galleryUrls back to
 * null/[] every time it runs, because Thunderstore's experimental per-package
 * endpoint (which it calls) doesn't expose richer versions of any of them.
 * The v1 catalogue endpoint THIS script calls happens to carry a bit more
 * (e.g. per-version `file_size`) — but writing that in now only for the next
 * verify-gamemods.ts run to erase it back to null would make the catalogue's
 * numbers visibly flap on every cron cycle for no benefit. So, deliberately,
 * this script writes the exact same null/[] values verifyThunderstore() does:
 *   license: null · gameVersions: [] · loaders: [] · fileBytes: null ·
 *   serverSide: null · galleryUrls: []
 * `downloads` and `dependencyCount` are matched to the SAME definition
 * verifyThunderstore() uses too — the LATEST version's own numbers
 * (`pkg.latest.downloads` / `pkg.latest.dependencies.length`), NOT a sum
 * across a package's whole version history — so a value this script writes
 * and a value the next verify pass writes never disagree over what
 * "downloads" even means for the same package.
 * `authorName` is the package's real owner/namespace (Thunderstore has no
 * separate "original author" field anywhere in its API distinct from the
 * uploading team — checked live; verifyThunderstore() makes the same call).
 * `authorAvatarUrl` stays null (no per-user avatar exists in this API).
 *
 * ---------------------------------------------------------------------------
 * QUALITY GATE (documented, not guessed)
 * ---------------------------------------------------------------------------
 * Applied to ALL four communities:
 *   - Skip `is_deprecated` packages. Real, and large: 5,282 of valheim's
 *     11,522 packages (45.8%) are deprecated — importing them as live
 *     catalogue content would be actively wrong, not just noisy.
 *   - Skip `has_nsfw_content` packages. Small (79/11522 valheim, 1/81 SOTF,
 *     5/523 schedule-i, 0/45 sunkenland) but a real, free, API-native signal
 *     a customer-facing hosting storefront should act on.
 *   - Skip packages tagged `Client-side` in `categories` UNLESS also tagged
 *     `Server-side`. This is Thunderstore's loose analogue of Modrinth's
 *     `environment` facet, and this repo's own GameMod.serverSide doc comment
 *     already states the principle: "a client-only mod cannot be installed
 *     on a server at all, and the catalogue should not offer it." Only
 *     valheim actually uses this tag pair in practice (checked live across
 *     all 4 communities); it removes 680 client-only packages there. A
 *     package with NEITHER tag is kept (ambiguous, not evidence of
 *     client-only — same reasoning Modrinth's own "plugin + unknown" carve-out
 *     used for an analogous gap).
 * Applied to valheim ONLY (min-downloads floor):
 *   - Latest-version downloads > 1,000 (DEFAULT_MIN_DOWNLOADS_VALHEIM,
 *     override with --min-downloads). Needed because valheim alone is
 *     11.5k packages deep — the other three communities (81 / 523 / 45 raw
 *     packages) are already small enough that a floor would just discard
 *     real, legitimate niche content without solving any actual scale
 *     problem (sunkenland's OWN 45-package total makes this obvious: there
 *     is no "top slice" to cut, you import what's there). Checked live: of
 *     valheim's 5,033 packages that clear the deprecated+client-only gates,
 *     1,235 clear latest-version-downloads>1000 too — a real ~25% cut,
 *     comparable in spirit (not identical numbers) to how selective
 *     Modrinth's own downloads>1000-OR-follows>50 gate is over its full
 *     catalogue.
 *   - Modrinth's script also runs a second, disjoint pass on `follows` to
 *     catch newer-but-well-liked projects the downloads floor alone would
 *     miss. Tried the Thunderstore equivalent (`rating_score`, the closest
 *     thing Thunderstore has to "follows") before deciding against it:
 *     checked live how many valheim packages have rating_score>20 AND
 *     downloads<=1000 (i.e. what a disjoint second pass would actually add)
 *     — zero. On Thunderstore, rating and downloads correlate too tightly
 *     for a second pass to catch anything a single downloads floor doesn't
 *     already have. Documenting the finding here instead of carrying a
 *     provably-dead code path.
 *
 * ---------------------------------------------------------------------------
 * IDENTITY / SLUG STRATEGY (why this isn't a plain slugify-and-go)
 * ---------------------------------------------------------------------------
 * Real identity on Thunderstore is `full_name` (`{owner}-{name}`), globally
 * unique — that's what's stored in `sourceId`, and it's the same value
 * `worker/game-mods.ts`'s `resolveUrl()` already parses to hit the real
 * per-package API at install time. `slug` is a separate, repo-local, kebab
 * identifier that only has to be unique per gameFamily — but Phase 1 already
 * hand-picked human-friendly slugs for 21 valheim/thunderstore rows (e.g.
 * sourceId "denikson-BepInExPack_Valheim" → slug "bepinex-valheim") that a
 * mechanical kebab-case of `full_name` would NOT reproduce
 * ("denikson-bepinexpack-valheim"). Re-deriving slugs mechanically for
 * packages that already have a row would therefore silently create a SECOND
 * row for the same real package instead of upserting onto the first one —
 * exactly the duplication this script must not cause.
 * So: for every package, look up an existing row by (gameFamily, source:
 * "thunderstore", sourceId) FIRST. Found → reuse its existing slug verbatim
 * (never touch slug on update). Not found → mechanically slugify(full_name),
 * de-duplicated against every slug already used in that gameFamily (existing
 * rows + everything already assigned earlier in this same run), suffixing
 * -2/-3/... on collision. The actual write is still a plain
 * `db.gameMod.upsert` on the real `@@unique([gameFamily, slug])` constraint,
 * same as Modrinth's script — the sourceId lookup only decides WHICH slug to
 * upsert on. Re-running the script finds the same sourceId → same slug →
 * pure update, created=0, same idempotency contract as Modrinth's script.
 *
 * `popularity` and `featured` are deliberately left OUT of the write payload
 * entirely — on create they get Prisma's real defaults (0 / false), and on
 * update they are never touched, so Phase 1's genuine editorial calls (e.g.
 * BepInExPack/Jotunn hand-marked `featured: true`) survive this bulk pass
 * untouched. This matches import-modrinth-catalog.ts's own `data` object,
 * which never sets popularity/featured either.
 *
 * ---------------------------------------------------------------------------
 * KNOWN GAP, DOCUMENTED RATHER THAN SILENTLY LEFT (not this script's job to fix)
 * ---------------------------------------------------------------------------
 * `lib/mod-install-support.ts`'s INSTALLABLE_FAMILIES is {minecraft, rust,
 * valheim} — sonsoftheforest/schedule1/sunkenland are NOT in it yet, so
 * their imported rows will render with "install it yourself in Files"
 * rather than a one-click Install button (installSupport()'s documented,
 * intentional degrade — the same state ~178 of the Modrinth-side entries are
 * already in for families the worker can't reach, per that module's own
 * comment). `RESOLVABLE_SOURCES` already includes "thunderstore" and
 * `resolveUrl()`'s thunderstore case is source-keyed, not family-keyed, so it
 * already works correctly for these three families' packages the moment
 * their family gains a `modDirShell` case — that's real, separate follow-up
 * work (adding directory-discovery shell snippets for three more games),
 * not a blocker for importing the catalogue data itself.
 *
 * SAFETY: same as every other writing script in this repo — dry run by
 * default, `scripts/db-target-guard.ts` enforces NXEON_DB_TARGET.
 *
 *   Dry run, one small community first:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-thunderstore-catalog.ts \
 *       --communities=sunkenland
 *
 *   Real write, same slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-thunderstore-catalog.ts \
 *       --communities=sunkenland --apply
 *
 *   Full real run (all 4 communities, default thresholds):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-thunderstore-catalog.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-thunderstore-catalog.ts");

import { db } from "../lib/db";
import type { GameFamily } from "../lib/games";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const DEFAULT_MIN_DOWNLOADS_VALHEIM = 1000;
const REQUEST_TIMEOUT_MS = 120_000;

const ALL_COMMUNITIES = ["valheim", "sons-of-the-forest", "schedule-i", "sunkenland"] as const;
type Community = (typeof ALL_COMMUNITIES)[number];

/** Checked live against lib/games.ts's GAME_FAMILIES and lib/game-control.ts's GAME_CONTROL — see file header. */
const COMMUNITY_TO_FAMILY: Record<Community, GameFamily> = {
  valheim: "valheim",
  "sons-of-the-forest": "sonsoftheforest",
  "schedule-i": "schedule1",
  sunkenland: "sunkenland",
};

/** Communities that get a min-downloads floor, and what it is. Only valheim's
 *  catalogue is large enough to need one — see file header QUALITY GATE. */
const MIN_DOWNLOADS_FLOOR: Partial<Record<Community, number>> = {
  valheim: DEFAULT_MIN_DOWNLOADS_VALHEIM,
};

/** Thunderstore package category tags → this repo's category vocabulary
 *  (Admin/Content/Building/QoL/Core/Tweaks/Modpacks — the same buckets
 *  Phase 1's 21 hand-picked rows already use). Thunderstore's own tags are
 *  noisy per-community free text (seasonal update names, loader variants,
 *  a near-universal "Mods"), unlike Modrinth's fixed project_type, so this
 *  is a best-effort priority match against the few tags that actually carry
 *  real category meaning; anything else — including the very common "Mods",
 *  "Misc", "Utility"-without-"Tools", seasonal update names, "AI Generated",
 *  language tags — falls through to the generic "Content" bucket, same as
 *  Modrinth's own default bucket for anything it can't classify further. */
const CATEGORY_RULES: Array<[string, string]> = [
  ["Modpacks", "Modpacks"],
  ["Libraries", "Core"],
  ["Tweaks", "Tweaks"],
  ["Building", "Building"],
  ["Tools", "Admin"],
];
function categoryFor(categories: string[]): string {
  for (const [raw, mapped] of CATEGORY_RULES) {
    if (categories.includes(raw)) return mapped;
  }
  return "Content";
}

function slugify(fullName: string): string {
  const s = fullName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return s.slice(0, 80) || "mod";
}

// ── Thunderstore v1 catalogue types (only the fields we read) ───────────────
type PackageVersion = {
  icon?: string | null;
  description?: string | null;
  download_url?: string;
  downloads?: number;
  date_created?: string;
  dependencies?: unknown[];
};
type Package = {
  name: string;
  full_name: string;
  owner: string;
  package_url: string;
  categories?: string[];
  is_deprecated?: boolean;
  has_nsfw_content?: boolean;
  versions?: PackageVersion[];
};

/** The version with the newest date_created — versions[] isn't documented as
 *  sorted, so this doesn't assume it (confirmed live it usually is newest-
 *  first, but "usually" isn't good enough for what we treat as ground truth). */
function latestVersion(pkg: Package): PackageVersion | null {
  const vs = pkg.versions ?? [];
  if (vs.length === 0) return null;
  return vs.reduce((a, b) => (new Date(b.date_created ?? 0) > new Date(a.date_created ?? 0) ? b : a));
}

function isClientOnly(categories: string[]): boolean {
  return categories.includes("Client-side") && !categories.includes("Server-side");
}

function displayNameFrom(rawName: string): string {
  return rawName.replace(/_/g, " ").trim() || rawName;
}

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const communitiesArg = get("communities");
  const communities = (communitiesArg ? communitiesArg.split(",") : [...ALL_COMMUNITIES]).filter(
    (c): c is Community => (ALL_COMMUNITIES as readonly string[]).includes(c)
  );
  return {
    apply: argv.includes("--apply"),
    minDownloadsValheim: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS_VALHEIM),
    limit: get("limit") ? Number(get("limit")) : undefined, // smoke-test cap on ELIGIBLE packages processed per community
    communities: communities.length ? communities : [...ALL_COMMUNITIES],
  };
}

type Counters = { raw: number; deprecated: number; nsfw: number; clientOnly: number; belowFloor: number; eligible: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { raw: 0, deprecated: 0, nsfw: 0, clientOnly: 0, belowFloor: 0, eligible: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function fetchCommunity(community: Community): Promise<Package[]> {
  const url = `https://thunderstore.io/c/${community}/api/v1/package/`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const res = await fetch(url, { headers: { "User-Agent": UA }, signal: controller.signal });
    if (!res.ok) throw new Error(`Thunderstore API returned HTTP ${res.status} for ${community}`);
    return (await res.json()) as Package[];
  } finally {
    clearTimeout(timer);
  }
}

async function importCommunity(opts: { community: Community; apply: boolean; minDownloadsFloor: number; limit?: number }) {
  const { community, apply, minDownloadsFloor, limit } = opts;
  const gameFamily = COMMUNITY_TO_FAMILY[community];
  const counters = emptyCounters();

  console.log(`\n=== ${community} → gameFamily "${gameFamily}" ===`);
  console.log(`  fetching full catalogue (single request, no pagination)...`);
  const all = await fetchCommunity(community);
  counters.raw = all.length;
  console.log(`  fetched ${all.length} raw packages`);

  // Preload every existing thunderstore row for this family — this is what
  // makes the slug strategy (see file header) work without a per-package
  // DB round trip: sourceId → existing slug, plus every slug already in use.
  const existingRows = await db.gameMod.findMany({
    where: { gameFamily, source: "thunderstore" },
    select: { slug: true, sourceId: true },
  });
  const slugBySourceId = new Map<string, string>();
  const usedSlugs = new Set<string>();
  for (const row of existingRows) {
    usedSlugs.add(row.slug);
    if (row.sourceId) slugBySourceId.set(row.sourceId, row.slug);
  }
  console.log(`  ${existingRows.length} existing thunderstore row(s) already in this family`);

  const eligible: Array<{ pkg: Package; latest: PackageVersion }> = [];
  for (const pkg of all) {
    if (pkg.is_deprecated) {
      counters.deprecated++;
      continue;
    }
    if (pkg.has_nsfw_content) {
      counters.nsfw++;
      continue;
    }
    const categories = pkg.categories ?? [];
    if (isClientOnly(categories)) {
      counters.clientOnly++;
      continue;
    }
    const latest = latestVersion(pkg);
    if (!latest) {
      counters.skipped++;
      continue;
    }
    const downloads = typeof latest.downloads === "number" ? latest.downloads : 0;
    if (downloads <= minDownloadsFloor) {
      counters.belowFloor++;
      continue;
    }
    eligible.push({ pkg, latest });
  }
  counters.eligible = eligible.length;
  const toProcess = limit ? eligible.slice(0, limit) : eligible;
  console.log(
    `  gate: raw=${counters.raw} deprecated=${counters.deprecated} nsfw=${counters.nsfw} client-only=${counters.clientOnly} ` +
      `below-floor(>${minDownloadsFloor})=${counters.belowFloor} eligible=${counters.eligible}` +
      (limit ? ` (processing first ${toProcess.length} per --limit)` : "")
  );

  const CONCURRENCY = 8;
  for (let i = 0; i < toProcess.length; i += CONCURRENCY) {
    const slice = toProcess.slice(i, i + CONCURRENCY);
    await Promise.all(
      slice.map(async ({ pkg, latest }) => {
        if (!pkg.full_name || !pkg.owner) {
          counters.skipped++;
          return;
        }
        // Resolve slug: reuse an existing row's slug (Phase 1's hand-picked
        // ones included) if this exact package already has one; otherwise
        // mint a fresh, collision-checked one. See file header.
        let slug = slugBySourceId.get(pkg.full_name);
        const isNewRow = !slug;
        if (!slug) {
          const base = slugify(pkg.full_name);
          slug = base;
          let n = 2;
          while (usedSlugs.has(slug)) {
            slug = `${base}-${n}`;
            n++;
          }
          usedSlugs.add(slug);
          slugBySourceId.set(pkg.full_name, slug);
        }

        const data = {
          name: displayNameFrom(pkg.name),
          category: categoryFor(pkg.categories ?? []),
          description: latest.description || null,
          iconUrl: latest.icon ?? null,
          url: pkg.package_url,
          downloads: typeof latest.downloads === "number" ? latest.downloads : null,
          // See file header "FIELD SEMANTICS MUST MATCH verifyThunderstore()":
          license: null,
          gameVersions: [] as string[],
          loaders: [] as string[],
          serverSide: null,
          galleryUrls: [] as string[],
          fileBytes: null,
          dependencyCount: latest.dependencies?.length ?? 0,
          authorName: pkg.owner,
          authorAvatarUrl: null,
          source: "thunderstore",
          sourceId: pkg.full_name,
          active: true,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote: null,
        };

        if (!apply) {
          counters.upserted++;
          if (isNewRow) counters.created++;
          else counters.updated++;
          return;
        }
        try {
          await db.gameMod.upsert({
            where: { gameFamily_slug: { gameFamily, slug: slug! } },
            update: data,
            create: { gameFamily, slug: slug!, ...data },
          });
          counters.upserted++;
          if (isNewRow) counters.created++;
          else counters.updated++;
        } catch (e) {
          counters.failed++;
          const msg = e instanceof Error ? e.message : String(e);
          console.error(`  [db] failed to upsert ${gameFamily}/${slug}: ${msg}`);
        }
      })
    );
  }

  console.log(
    `--- ${community} done: upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} ` +
      `skipped=${counters.skipped} failed=${counters.failed} ---`
  );
  return counters;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(
    `[import-thunderstore-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
      `communities: ${args.communities.join(", ")}; valheim min-downloads floor: ${args.minDownloadsValheim}` +
      (args.limit ? `; limit=${args.limit} per community (smoke test)` : "")
  );

  const perCommunity: Record<string, Counters> = {};
  for (const community of args.communities) {
    const minDownloadsFloor = community === "valheim" ? args.minDownloadsValheim : (MIN_DOWNLOADS_FLOOR[community] ?? 0);
    perCommunity[community] = await importCommunity({ community, apply: args.apply, minDownloadsFloor, limit: args.limit });
  }

  const totals = emptyCounters();
  for (const c of Object.values(perCommunity)) {
    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += c[k];
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  for (const community of args.communities) {
    const c = perCommunity[community]!;
    console.log(
      `  ${community.padEnd(20)} raw=${c.raw.toString().padStart(6)} eligible=${c.eligible.toString().padStart(6)} ` +
        `upserted=${c.upserted.toString().padStart(6)} created=${c.created.toString().padStart(6)} updated=${c.updated.toString().padStart(6)} skipped=${c.skipped} failed=${c.failed}`
    );
  }
  console.log(
    `  ${"TOTAL".padEnd(20)} raw=${totals.raw.toString().padStart(6)} eligible=${totals.eligible.toString().padStart(6)} ` +
      `upserted=${totals.upserted.toString().padStart(6)} created=${totals.created.toString().padStart(6)} updated=${totals.updated.toString().padStart(6)} skipped=${totals.skipped} failed=${totals.failed}`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

